package cz.mh.rallye.rallye_backend.simulation;
import java.util.*;import java.time.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;import org.springframework.context.annotation.Import;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;
import cz.mh.rallye.rallye_backend.simulation.api.SimulationController;import cz.mh.rallye.rallye_backend.simulation.application.*;import cz.mh.rallye.rallye_backend.identity.api.*;import cz.mh.rallye.rallye_backend.identity.application.*;import cz.mh.rallye.rallye_backend.competition.domain.GpsParser;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
@WebMvcTest(SimulationController.class) @Import({AuthConfiguration.class,AuthCookies.class,ApiErrors.class})
class SimulationHttpTest {
 @Autowired MockMvc mvc;@MockitoBean AuthService auth;@MockitoBean SimulationService service;
 final String base="/api/v1/admin/race-simulations",token=new SecretTokens().create();final UUID id=UUID.randomUUID(),run=UUID.randomUUID(),stage=UUID.randomUUID();final AuthService.Principal actor=new AuthService.Principal(UUID.randomUUID(),UUID.randomUUID(),false);
 void login(boolean admin){when(auth.authenticate(token)).thenReturn(actor);when(auth.isAdministrator(actor)).thenReturn(admin);}
 String code(){return "{\"version\":0,\"runId\":\""+run+"\",\"stageId\":\""+stage+"\",\"code\":\"INPUT-ONLY\"}";}
 @Test void historyReturnsExplicitInputsWithoutChangingInt64Strings()throws Exception{
  login(true);var at=Instant.parse("2026-10-29T10:00:00Z");
  var in=new cz.mh.rallye.rallye_backend.simulation.persistence.SimulationStore.ConfirmedInput("9007199254740993",run,stage,"  MiXeD  ",null,null,null,null,null,null,null);
  var item=new SimulationService.HistoryItem(UUID.randomUUID(),1,"CODE",stage,at,"CODE_REJECTED","3",List.of(),in,null,null,new SimulationService.HistoryClock(at,at),null);
  when(service.history(actor,id,run,0,50)).thenReturn(new SimulationService.HistoryPage(id,run,List.of(item),false,1));
  mvc.perform(get(base+"/"+id+"/history").param("runId",run.toString()).header("Authorization","Bearer "+token))
   .andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"))
   .andExpect(jsonPath("$.items[0].input.code").value("  MiXeD  "))
   .andExpect(jsonPath("$.items[0].input.version").value("9007199254740993"))
   .andExpect(jsonPath("$.items[0].clockChange.before").value(at.toString()));
 }
 @Test void anonymousAndUserCannotUseAnyRoutes()throws Exception{mvc.perform(get(base+"/"+id)).andExpect(status().isUnauthorized());login(false);for(String suffix:List.of("","/current-stage","/dashboard","/files","/history?runId="+run))mvc.perform(get(base+"/"+id+suffix).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());mvc.perform(post(base+"/"+id+"/code-attempts").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(code())).andExpect(status().isForbidden());verifyNoInteractions(service);}
 @Test void codeBearerAndCookieCsrfArePreserved()throws Exception{login(true);String url=base+"/"+id+"/code-attempts";mvc.perform(post(url).cookie(new Cookie(AuthCookies.NAME,token)).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(code())).andExpect(status().isForbidden());verifyNoInteractions(service);mvc.perform(post(url).cookie(new Cookie(AuthCookies.NAME,token)).with(csrf().asHeader()).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(code())).andExpect(status().isOk());mvc.perform(post(url).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(code())).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));verify(service,times(2)).mutate(eq(actor),eq(id),any(),eq("CODE"),argThat(in->in.version()==0&&in.runId().equals(run)&&in.stageId().equals(stage)&&in.code().equals("INPUT-ONLY")));}
 @Test void strictFieldsVersionsAndRequiredKeyAreValidated()throws Exception{login(true);for(String json:List.of("{}",code().replace("\"version\":0","\"version\":-1"),code().replace("\"version\":0","\"version\":0.5"),code().replace("\"version\":0","\"points\":3,\"version\":0"),code().replace("\"INPUT-ONLY\"","null"))){mvc.perform(post(base+"/"+id+"/code-attempts").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(json)).andExpect(status().isBadRequest());}mvc.perform(post(base+"/"+id+"/code-attempts").header("Authorization","Bearer "+token).contentType("application/json").content(code())).andExpect(status().isBadRequest());verifyNoInteractions(service);}
 @Test void createAndMinuteTimeUseContract()throws Exception{login(true);var view=new SimulationView.View(id,run,0,"RUNNING",null,null,null,null,null,null,Instant.parse("2026-10-30T10:00:00Z"),null);when(service.create(eq(actor),eq(stage),eq(5L),any(),eq(Instant.parse("2026-10-29T10:00:00Z")))).thenReturn(view);mvc.perform(post(base).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{\"templateId\":\""+stage+"\",\"templateVersion\":5,\"virtualStartAt\":\"2026-10-29T10:00:00Z\"}")).andExpect(status().isCreated()).andExpect(header().string("Location",base+"/"+id)).andExpect(jsonPath("$.version").value(0)).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("INPUT-ONLY"))));}
 @Test void positionModesAndNegativeTimeAreDistinct()throws Exception{login(true);String common="\"version\":0,\"runId\":\""+run+"\"";mvc.perform(post(base+"/"+id+"/clock-shifts").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{"+common+",\"deltaMs\":-1000}")).andExpect(status().isOk());verify(service).mutate(eq(actor),eq(id),any(),eq("CLOCK_SHIFT"),argThat(i->i.deltaMs()==-1000));mvc.perform(put(base+"/"+id+"/position").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{"+common+",\"mode\":\"INPUT\",\"latitude\":50,\"longitude\":14,\"accuracyMeters\":0,\"mockLocation\":false}")).andExpect(status().isOk());mvc.perform(put(base+"/"+id+"/position").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content("{"+common+",\"mode\":\"UNAVAILABLE\",\"latitude\":50}")).andExpect(status().isBadRequest());}
 @Test void offlineParserAndErrorContracts()throws Exception{login(true);when(service.parse(actor,"N50 05.247 E014 25.240")).thenReturn(GpsParser.parse("N50 05.247 E014 25.240"));mvc.perform(post(base+"/coordinates/parse").header("Authorization","Bearer "+token).contentType("application/json").content("{\"text\":\"N50 05.247 E014 25.240\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.format").value("DMM"));when(service.get(actor,id)).thenThrow(new AuthFailure(404,"SIMULATION_NOT_FOUND"));mvc.perform(get(base+"/"+id).header("Authorization","Bearer "+token)).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("SIMULATION_NOT_FOUND"));}
 @Test void quizIsNotAnImplementedGameAndBodyIsRedacted()throws Exception{login(true);mvc.perform(post(base+"/"+id+"/quiz-answers").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(code().replace(",\"code\":\"INPUT-ONLY\"",""))).andExpect(status().isNotImplemented()).andExpect(jsonPath("$.code").value("SIMULATION_QUIZ_UNSUPPORTED"));verify(service,never()).mutate(any(),any(),any(),any(),any());}
 @Test void fileDownloadsKeepPrivateHeaders()throws Exception{login(true);when(service.file(actor,id,"rules.pdf")).thenReturn(new SimulationService.Content("rules.pdf","application/pdf",new byte[]{1},false,true));mvc.perform(get(base+"/"+id+"/files/rules.pdf").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(header().string("Referrer-Policy","no-referrer")).andExpect(header().string("X-Content-Type-Options","nosniff")).andExpect(header().string("Content-Disposition",org.hamcrest.Matchers.startsWith("attachment")));}

 @Test void listAndDeleteUseExistingAdminCsrfAndPagingContract()throws Exception{
  login(false);mvc.perform(get(base).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());verify(service,never()).list(any(),any(),anyInt(),anyInt());
  login(true);when(service.list(actor,"RUNNING",1,2)).thenReturn(new SimulationService.Page(List.of(),1,2,false));
  mvc.perform(get(base).param("status","RUNNING").param("page","1").param("size","2").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$.page").value(1)).andExpect(jsonPath("$.hasMore").value(false)).andExpect(header().string("Cache-Control","no-store"));
  mvc.perform(delete(base+"/"+id).param("version","0").header("Authorization","Bearer "+token)).andExpect(status().isNoContent());verify(service).delete(actor,id,0);
  when(auth.authenticate(any())).thenReturn(actor);Cookie session=new Cookie("RALLYE_SESSION",token);
  mvc.perform(delete(base+"/"+id).param("version","0").cookie(session)).andExpect(status().isForbidden());
 }

 @Test void organizerLifecycleUsesStrictBodyAdminOwnerServiceAndCsrf()throws Exception{
  String body="{\"version\":0,\"runId\":\""+run+"\"}";
  login(false);mvc.perform(post(base+"/"+id+"/race-starts").header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isForbidden());verifyNoInteractions(service);
  login(true);
  for(String endpoint:List.of("race-starts","race-ends")){
   mvc.perform(post(base+"/"+id+"/"+endpoint).cookie(new Cookie(AuthCookies.NAME,token)).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isForbidden());
   mvc.perform(post(base+"/"+id+"/"+endpoint).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));
   mvc.perform(post(base+"/"+id+"/"+endpoint).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body.replace("}",",\"at\":\"2026-10-29T00:00:00Z\"}"))).andExpect(status().isBadRequest());
  }
  verify(service).mutate(eq(actor),eq(id),any(),eq("RACE_START"),argThat(i->i.runId().equals(run)&&i.stageId()==null&&i.version()==0));
  verify(service).mutate(eq(actor),eq(id),any(),eq("RACE_END"),any());
 }

 @Test void radarAndInformationUseExistingVersionCsrfAndIdempotencyContract()throws Exception{login(true);String body=code().replace(",\"code\":\"INPUT-ONLY\"","");for(String route:List.of("radar-measurements","stage-completions")){mvc.perform(post(base+"/"+id+"/"+route).cookie(new Cookie(AuthCookies.NAME,token)).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isForbidden());mvc.perform(post(base+"/"+id+"/"+route).header("Authorization","Bearer "+token).header("Idempotency-Key",UUID.randomUUID()).contentType("application/json").content(body)).andExpect(status().isOk());}verify(service).mutate(eq(actor),eq(id),any(),eq("RADAR"),argThat(i->i.stageId().equals(stage)));verify(service).mutate(eq(actor),eq(id),any(),eq("COMPLETE"),any());}

 @Test void radarHistoryIsPrivateAndReturnsOnlyExplicitMeasurementFields()throws Exception{
  String url=base+"/"+id+"/runs/"+run+"/stages/"+stage+"/radar-measurements";
  mvc.perform(get(url)).andExpect(status().isUnauthorized());login(false);mvc.perform(get(url).header("Authorization","Bearer "+token)).andExpect(status().isForbidden());verifyNoInteractions(service);
  login(true);var at=Instant.parse("2026-10-30T10:00:00Z");var item=new SimulationService.RadarMeasurement(UUID.randomUUID(),run,3,1,51.123456789,15.987654321,1234,"9007199254740993",at,at,false);when(service.radarHistory(actor,id,run,stage,0,50)).thenReturn(new SimulationService.RadarHistory(id,run,stage,List.of(item),false,3));
  mvc.perform(get(url).header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.items[0].latitude").value(51.123456789)).andExpect(jsonPath("$.items[0].distanceMeters").value(1234)).andExpect(jsonPath("$.items[0].penaltyPoints").value("9007199254740993")).andExpect(jsonPath("$.items[0].completedStage").value(false)).andExpect(jsonPath("$.items[0]",org.hamcrest.Matchers.aMapWithSize(11))).andExpect(jsonPath("$.targetLatitude").doesNotExist()).andExpect(jsonPath("$.items[0].gps").doesNotExist());
  mvc.perform(get(url).param("afterSequence","invalid").header("Authorization","Bearer "+token)).andExpect(status().isBadRequest());verify(service).radarHistory(actor,id,run,stage,0,50);
 }
}
